SELECT c.id, c.text, c.institution_code institutionCode FROM (select a.SCENE_ID id, a.SCENE_NAME text, a.institution_code, a.is_tmpl , b.tips_value as riskType ,a.eff_status eff_status FROM STT_SCENE a left join stt_scene_tips b on a.scene_id = b.scene_id and b.dict_code = 'RISK_TYPE' )c
c.is_tmpl='02'
and c.eff_status = #{effStatus, jdbcType=VARCHAR}
and c.riskType = #{riskType, jdbcType=VARCHAR}
AND (c.id like concat('%',concat(#{scene,jdbcType=VARCHAR},'%')) OR c.text like concat('%',concat(#{scene,jdbcType=VARCHAR},'%')) )


select 
	t.PORTFOLIO_ID id,
	m.PORTFOLIO_NAME name,
	m.PROFIT_TYPE pId      
from PA_PTL_PORTFOLIO t
inner join  PTL_PORTFOLIO m
on t.PORTFOLIO_ID=m.PORTFOLIO_ID



		t.PORTFOLIO_ID not in (select PORTFOLIO_ID from RSK_PORTFOLIO_INDICATOR where PORTFOLIO_LEVEL =#{portfLevel} and IND_ID =#{indId} )


		and t.PORTFOLIO_ID IN 

  			#{item}



		and m.PROFIT_TYPE = #{profitType}


		and t.OPEN_TYPE = #{issueMode}


		and t.RAISE_TYPE = #{raiseType}


		and t.INVEST_NATURE = #{investType}


		and m.PORTFOLIO_TYPE = #{portfolioType}

 	select 
	 	t.PORTFOLIO_ID id,
	 	m.PORTFOLIO_NAME name,${fields} as pId       
	from PA_PTL_PORTFOLIO t
	inner join  PTL_PORTFOLIO m
	on t.PORTFOLIO_ID=m.PORTFOLIO_ID


			t.PORTFOLIO_ID not in (select PORTFOLIO_ID from RSK_PORTFOLIO_INDICATOR where PORTFOLIO_LEVEL =#{portfLevel} and IND_ID =#{indId} )


			and t.PORTFOLIO_ID IN 

	  			#{item}



			and m.PROFIT_TYPE = #{profitType}


			and t.OPEN_TYPE = #{issueMode}


			and t.RAISE_TYPE = #{raiseType}


			and t.INVEST_NATURE = #{investType}


			and m.PORTFOLIO_TYPE = #{portfolioType}
